using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve "Discriminator" property name for existing documents (was renamed to "$type" in EF Core 9)
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Preserve old compound id format "Blog|1" for existing documents (EF Core 9 uses key-only ids)
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // HasIndex throws in EF Core 9 Cosmos provider — remove it;
        // manage indexing via Azure Portal or infrastructure-as-code.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

